-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd(SCRIPTS .. "/powercheck")
    hl.exec_cmd(SCRIPTS .. "/portal.sh")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("/usr/lib/pam_kwallet_init")
    hl.exec_cmd("wl-paste -t text -w xclip -selection clipboard")
end)

-- Exec (run every reload)
hl.on("config.reloaded", function()
    --hl.exec_cmd(TERMSERVER)
    hl.exec_cmd("pkill swayidle; swayidle -w timeout 1500 '$LOCK' timeout 3600 'hyprctl dispatch dpms off' resume 'hyprctl dispatch dpms on' before-sleep '$LOCK'")
end)
